{"path": "/tmp/sv-4d23d11a41b34fc1a0e59ba814db705d/Components/Chat/MessageInput.razor", "file_text": "<div class="message-input-area">
    <textarea class="message-textarea" @bind="messageText" @bind:event="oninput"
              placeholder="@Placeholder" @onkeydown="HandleKeyDown"></textarea>
    <button class="btn-send" @onclick="Send" disabled="@string.IsNullOrWhiteSpace(messageText)">
        @ButtonLabel
    </button>
</div>

@code {
    [Parameter] public string Placeholder { get; set; } = "Type a message…";
    [Parameter] public string ButtonLabel { get; set; } = "Send";
    [Parameter] public EventCallback<string> OnSend { get; set; }

    private string messageText = string.Empty;

    private async Task HandleKeyDown(Microsoft.AspNetCore.Components.Web.KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await Send();
        }
    }

    private async Task Send()
    {
        if (string.IsNullOrWhiteSpace(messageText)) return;
        var text = messageText.Trim();
        messageText = string.Empty;
        await OnSend.InvokeAsync(text);
    }
}
"}

