+    transition: background-color 0.1s;
+}
+
+.emoji-option:hover {
+    background-color: #e9ecef;
+}
+
+/* ===== Message Input ===== */
+.message-input-area {
+    display: flex;
+    gap: 0.5rem;
+    padding: 0.8rem 1.2rem;
+    border-top: 1px solid #dee2e6;
+    background-color: #fff;
+}
+
+.message-textarea {
+    flex: 1;
+    resize: none;
+    border: 1px solid #ced4da;
+    border-radius: 6px;
+    padding: 0.5rem 0.75rem;
+    font-size: 0.9rem;
+    min-height: 40px;
+    max-height: 120px;
+    font-family: inherit;
+}
+
+.message-textarea:focus {
+    outline: none;
+    border-color: #86b7fe;
+    box-shadow: 0 0 0 0.2rem rgba(13, 110, 253, 0.15);
+}
+
+.btn-send {
+    align-self: flex-end;
+    background-color: #0d6efd;
+    color: white;
+    border: none;
+    border-radius: 6px;
+    padding: 0.5rem 1rem;
+    font-weight: 600;
+    font-size: 0.85rem;
+    cursor: pointer;
+    transition: background-color 0.15s;
+}
+
+.btn-send:hover:not(:disabled) {
+    background-color: #0b5ed7;
+}
+
+.btn-send:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* ===== Thread Panel ===== */
+.thread-panel {
+    width: 25%;
+    min-width: 280px;
+    border-left: 1px solid #dee2e6;
+    display: flex;
+    flex-direction: column;
+    background-color: #fff;
+}
+
+.thread-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    padding: 0.8rem 1rem;
+    border-bottom: 1px solid #dee2e6;
+}
+
+.thread-header h5 {
+    margin: 0;
+    font-weight: 700;
+}
+
+.btn-close-thread {
+    background: none;
+    border: none;
+    font-size: 1.2rem;
+    cursor: pointer;
+    color: #6c757d;
+    padding: 4px 8px;
+    border-radius: 4px;
+}
+
+.btn-close-thread:hover {
+    background-color: #e9ecef;
+}
+
+.thread-root-message {
+    padding: 0.8rem 1rem;
+    background-color: #f8f9fa;
+    border-bottom: 1px solid #dee2e6;
+}
+
+.thread-root-message .message-author {
+    font-size: 0.85rem;
+}
+
+.thread-root-message .message-content {
+    font-size: 0.85rem;
+    color: #495057;
+}
+
+.thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 0.8rem 1rem;
+    display: flex;
+    flex-direction: column;
+    gap: 0.5rem;
+}
+
+.thread-reply {
+    padding: 0.4rem 0;
+    border-bottom: 1px solid #f1f3f5;
+}
+

